-- Trenerki Academy — idempotentny, bezpieczny patch treści kursu Kołodziej (2026-11-09).
-- Zakres: ta_lessons (16 lekcji), opisy kursu i preview. Nie modyfikuje uczniów, postępów, wyników, płatności, RLS ani flag publikacji.
BEGIN;
insert into public.ta_lessons(course_slug,lesson_no,title_pl,material) values
('kolodziej',0,'1. Anatomia drewnianego koła: piasta, szprychy, dzwona i obręcz','{"module":1,"curriculum_revision":6,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"kolodziej-przekroj","sections":[{"heading":"Fundamenty i pojęcia","text":"Koło wozowe nie jest drewnianym dyskiem z ozdobnymi promieniami. Składa się z piasty (hub), szprych (spokes), segmentów drewnianego obwodu zwanych dzwonami (felloes) oraz zewnętrznej metalowej obręczy (tyre). Otwór w piaście współpracuje z osią, szprychy łączą piastę z obwodem, a obręcz chroni segmenty drewna i spina cały układ. Nie utożsamiaj żelaznej obręczy z piastą ani dzwona z pojedynczą szprychą."},{"heading":"Narzędzia, proces i metoda","text":"Narysuj przekrój poprzeczny koła i jeden widok od przodu. Zaznacz czop szprychy w gnieździe piasty i drugi koniec szprychy w dzwonie. W rzeczywistym zabytkowym egzemplarzu liczba szprych i liczba dzwon może być inna: muzealny przykład z Walii zawiera 14 szprych i 7 jesionowych dzwon. Sam układ elementów trzeba odczytać, zanim cokolwiek zmierzysz."},{"heading":"Przykład z liczbami lub pomiarem","text":"Model z 14 szprychami i 7 dzwonami ma średnio 2 zakończenia szprych na jeden segment obwodu (14/7=2); to opis konkretnej konstrukcji, a nie reguła dotycząca wszystkich kół."},{"heading":"Sytuacja zawodowa","text":"Klient mówi, że odpadła ''szprycha'', lecz na fotografii widać szczelinę na połączeniu dwóch dzwon. Przed naprawą zidentyfikuj element i wyjaśnij, dlaczego postępowanie z pękniętym dzwonem różni się od wymiany szprychy."},{"heading":"Praca ucznia i kryteria sprawdzenia","text":"Na schemacie podpisz 8 elementów: oś, otwór osiowy, piasta, gniazdo, czop szprychy, szprycha, dzwono i obręcz stalowa. Następnie pokaż strzałkami schematyczną drogę sił w kole obciążonym."}],"references":[{"label":"Źródło fachowe lub muzealne","url":"https://museum.wales/collections/online/object/c92c1c74-5534-34bf-91d5-b6ade7331896/Cart-wheel/"}],"learning":{"intro":"Koło wozowe nie jest drewnianym dyskiem z ozdobnymi promieniami. Składa się z piasty (hub), szprych (spokes), segmentów drewnianego obwodu zwanych dzwonami (felloes) oraz zewnętrznej metalowej obręczy (tyre). Otwór w piaście współpracuje z osią, szprychy łączą piastę z obwodem, a obręcz chroni segmenty drewna i spina cały układ. Nie utożsamiaj żelaznej obręczy z piastą ani dzwona z pojedynczą szprychą.","situation":"Klient mówi, że odpadła ''szprycha'', lecz na fotografii widać szczelinę na połączeniu dwóch dzwon. Przed naprawą zidentyfikuj element i wyjaśnij, dlaczego postępowanie z pękniętym dzwonem różni się od wymiany szprychy.","task":"Na schemacie podpisz 8 elementów: oś, otwór osiowy, piasta, gniazdo, czop szprychy, szprycha, dzwono i obręcz stalowa. Następnie pokaż strzałkami schematyczną drogę sił w kole obciążonym.","question":"Zabytkowe koło ma 14 szprych i 7 dzwon. Ile zakończeń szprych przypada średnio na jedno dzwono w tym konkretnym układzie?","options":["Siedem, ponieważ każdy segment obejmuje połowę obwodu.","Czternaście, ponieważ szprychy łączą się parami na wspólnym końcu.","Dwa, ponieważ 14/7=2.","Jedno, ponieważ liczba dzwon jest połową liczby szprych."],"correct":2,"example":"Dwa, ponieważ 14/7=2.","explanation":"14 szprych dzielone przez 7 segmentów to średnio 2 końce szprych na segment. To parametr tej konstrukcji.","feedback":["Nie. Siedem to liczba samych dzwon, a nie końców szprych w jednym segmencie.","Nie. Czternaście jest liczbą szprych w całym kole, nie na jednym dzwonie.","Tak. 14/7=2; mówimy o średniej dla tego konkretnego koła.","Nie. Jedno odpowiadałoby przykładowo konstrukcji z taką samą liczbą dzwon i szprych."]}}'::jsonb),
('kolodziej',1,'2. Materiałoznawstwo: wiąz, dąb, jesion i dobór włókien','{"module":1,"curriculum_revision":6,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"kolodziej-drewno","sections":[{"heading":"Fundamenty i pojęcia","text":"Dobór drewna do koła zależy od funkcji elementu. W historycznych przykładach stosowano wiąz na piastę ze względu na odporność na rozłupywanie przy gniazdach, sezonowany dąb na szprychy o wymaganej sztywności, a jesion na dzwona łączące wytrzymałość z pewną elastycznością. To tradycyjne zestawienie, nie jedyny możliwy materiał dla każdego regionu czy pojazdu. Sama nazwa gatunku nie gwarantuje jakości: liczą się kierunek włókien, sęki, pęknięcia i warunki przechowywania."},{"heading":"Narzędzia, proces i metoda","text":"Oznacz próbki A, B, C. Zapisz gatunek i dokumentację pochodzenia, przebieg słojów, możliwe pęknięcia czołowe, miejscowe skręcenie włókien i wilgotność zmierzoną odpowiednią metodą. W miejscach czopów i gniazd nieakceptowalne defekty mogą szybko przejść w uszkodzenie konstrukcyjne. Nie zastępuj kontroli klasy materiału malowaniem drewna."},{"heading":"Przykład z liczbami lub pomiarem","text":"Dwie szprychy wykonane z dębu mają identyczną długość i grubość, ale jedna ma duży sęk na wąskim przekroju przy czopie. Mimo równego wymiaru nie muszą mieć podobnej niezawodności. Celem kontroli jest zidentyfikowanie wady oraz porównanie z kryterium odbioru."},{"heading":"Sytuacja zawodowa","text":"Dostawca proponuje drewno bez informacji o sezonowaniu, twierdząc, że jest ''bardzo twarde''. Wymień pytania o wilgotność, wady, włókna, przeznaczenie i wymagania zamawianego koła."},{"heading":"Praca ucznia i kryteria sprawdzenia","text":"Przygotuj tabelę trzech elementów (piasta/szprycha/dzwono) z gatunkiem tradycyjnie stosowanym, własnością uzasadniającą wybór, możliwą wadą i sposobem jej sprawdzenia. Obok narysuj sęk i odchylenie włókien."}],"references":[{"label":"Źródło fachowe lub muzealne","url":"https://www.hessenpark.de/en/lexikon/handwerk/vorfuehrungen/wagnerei/"}],"learning":{"intro":"Dobór drewna do koła zależy od funkcji elementu. W historycznych przykładach stosowano wiąz na piastę ze względu na odporność na rozłupywanie przy gniazdach, sezonowany dąb na szprychy o wymaganej sztywności, a jesion na dzwona łączące wytrzymałość z pewną elastycznością. To tradycyjne zestawienie, nie jedyny możliwy materiał dla każdego regionu czy pojazdu. Sama nazwa gatunku nie gwarantuje jakości: liczą się kierunek włókien, sęki, pęknięcia i warunki przechowywania.","situation":"Dostawca proponuje drewno bez informacji o sezonowaniu, twierdząc, że jest ''bardzo twarde''. Wymień pytania o wilgotność, wady, włókna, przeznaczenie i wymagania zamawianego koła.","task":"Przygotuj tabelę trzech elementów (piasta/szprycha/dzwono) z gatunkiem tradycyjnie stosowanym, własnością uzasadniającą wybór, możliwą wadą i sposobem jej sprawdzenia. Obok narysuj sęk i odchylenie włókien.","question":"Który tradycyjny dobór materiałów jest potwierdzony w historycznej praktyce kołodziejskiej opisanej przez Hessenpark?","options":["Wiąz na piastę, dąb na szprychy, jesion na dzwona.","Dąb na piastę, jesion na szprychy, wiąz na dzwona.","Jesion na piastę, wiąz na szprychy, dąb na dzwona.","Sosna na piastę, dąb na dzwona, jesion na szprychy."],"correct":0,"example":"Wiąz na piastę, dąb na szprychy, jesion na dzwona.","explanation":"Wiąz, dąb i jesion są opisane jako tradycyjny zestaw dla różnych stref obciążenia, nie uniwersalna recepta dla każdego koła.","feedback":["Tak. Taką kombinację opisuje Hessenpark, z zastrzeżeniem wymagań konkretnego wyrobu.","Nie. To inne przypisanie gatunków niż w udokumentowanym przykładzie.","Nie. To przestawienie funkcji opisanych w historycznym źródle.","Nie. Sosna i układ pozostałych gatunków nie odpowiadają opisowi wybranej tradycji."]}}'::jsonb),
('kolodziej',2,'3. Geometria koła: średnica, obwód i rozstaw szprych','{"module":1,"curriculum_revision":6,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"kolodziej-geometria","sections":[{"heading":"Fundamenty i pojęcia","text":"Do zaprojektowania koła potrzebujesz wymiarów średnicy zewnętrznej, średnicy obwodu drewnianego, średnicy otworu osiowego, długości piasty i położenia szprych. Zależność C=πD pozwala oszacować obwód idealnego koła. Równe rozstawienie N szprych odpowiada podziałowi pełnego kąta 360° na N części, ale rzeczywisty układ może uwzględniać przestrzenną geometrię i różne profile czopów."},{"heading":"Narzędzia, proces i metoda","text":"Dla przykładu dydaktycznego przyjmij D=900 mm i N=16. Obwód teoretyczny koła: π×900≈2827,43 mm. Rozstaw kątowy osi szprych: 360°/16=22,5°. Wynik nie jest długością metalowej obręczy produkcyjnej, ponieważ ta ma własny przekrój, średnicę osadzenia i wymagania pasowania. Wymiary z rysunku zapisuj w mm i zaznacz, na której powierzchni je mierzysz."},{"heading":"Przykład z liczbami lub pomiarem","text":"Koło o średnicy 900 mm nie może mieć obwodu 900 mm. Gdy monter poda do zamówienia 900 zamiast ~2827 mm, popełnia błąd mylenia średnicy z obwodem. Przy 16 szprychach nie wystarczy podzielić piastę na 16 części ''na oko''."},{"heading":"Sytuacja zawodowa","text":"W warsztacie masz projekt średnicy 900 mm, ale szablon dla koła 800 mm. Porównaj obwody: różnica to 100π≈314,16 mm. Wyjaśnij, dlaczego nie wystarczy dodać po 1 mm na każdy segment."},{"heading":"Praca ucznia i kryteria sprawdzenia","text":"Policz obwody dla D=600, 900 i 1200 mm; dla 12, 14 i 16 szprych policz podział kątowy. W osobnej kolumnie zaznacz dane, których nie można wyznaczyć bez projektu (grubość dzwona, pasowanie obręczy, długość czopu)."}],"references":[{"label":"Źródło fachowe lub muzealne","url":"https://metc.org/decoding-the-past-wheelwright/"}],"learning":{"intro":"Do zaprojektowania koła potrzebujesz wymiarów średnicy zewnętrznej, średnicy obwodu drewnianego, średnicy otworu osiowego, długości piasty i położenia szprych. Zależność C=πD pozwala oszacować obwód idealnego koła. Równe rozstawienie N szprych odpowiada podziałowi pełnego kąta 360° na N części, ale rzeczywisty układ może uwzględniać przestrzenną geometrię i różne profile czopów.","situation":"W warsztacie masz projekt średnicy 900 mm, ale szablon dla koła 800 mm. Porównaj obwody: różnica to 100π≈314,16 mm. Wyjaśnij, dlaczego nie wystarczy dodać po 1 mm na każdy segment.","task":"Policz obwody dla D=600, 900 i 1200 mm; dla 12, 14 i 16 szprych policz podział kątowy. W osobnej kolumnie zaznacz dane, których nie można wyznaczyć bez projektu (grubość dzwona, pasowanie obręczy, długość czopu).","question":"Koło o średnicy 900 mm z 16 równo rozmieszczonymi szprychami ma teoretyczny obwód i rozstaw kątowy równy...","options":["Obwód około 2827 mm; podział kątowy 16°. ","Obwód około 2827 mm; podział kątowy 22,5°. ","Obwód około 1414 mm; podział kątowy 22,5°. ","Obwód około 3142 mm; podział kątowy 30°."],"correct":1,"example":"Obwód około 2827 mm; podział kątowy 22,5°. ","explanation":"C=π×900≈2827 mm; 360°/16=22,5°. Są to obliczenia geometryczne, nie parametry pasowania metalowej obręczy.","feedback":["Nie. Obwód jest poprawny, ale 360/16 to 22,5°, nie 16°. ","Tak. π×900≈2827 mm, a 360/16=22,5°. ","Nie. 1414 mm to mniej więcej połowa obwodu, a nie całość.","Nie. Wartości odpowiadają innym założeniom D i N niż podane."]}}'::jsonb),
('kolodziej',3,'4. Rysunek techniczny i talerzowatość koła (dish)','{"module":1,"curriculum_revision":6,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"kolodziej-bicie","sections":[{"heading":"Fundamenty i pojęcia","text":"Koło dawnego wozu bywa celowo ''talerzowate'' (dished): szprychy nie leżą w jednej płaskiej tarczy, lecz tworzą geometryczne wychylenie. Ma ono związek z konstrukcją, obciążeniami i stabilnością całego zestawu. To nie to samo co przypadkowe boczne bicie koła. Rysunek musi pokazywać widok z przodu i przekrój przez piastę, a także stronę montażu koła względem pojazdu."},{"heading":"Narzędzia, proces i metoda","text":"Na arkuszu narysuj oś koła pionowo w widoku od przodu, a w przekroju bocznym pokaż linię płaszczyzny zewnętrznego obwodu i położenie piasty. Wpisz osobno: średnicę, głębokość wychylenia, szerokość piasty i położenie środka. Bez wymiaru ''dish'' nie można zakładać, że każdy punkt piasty i obwodu jest na tej samej płaszczyźnie."},{"heading":"Przykład z liczbami lub pomiarem","text":"Koło A ma projektowo wygięte szprychy i równe obwody przy obrocie; koło B ma bok koła przesuwający się względem stabilnego punktu pomiaru raz w lewo, raz w prawo. Pierwsze może być poprawną geometrią, a drugie objawem bicia bocznego."},{"heading":"Sytuacja zawodowa","text":"Praktykant widzi, że piasta nie jest w tej samej płaszczyźnie co obręcz, więc chce prostować wszystkie szprychy. Ustal, czy widzi zaprojektowaną talerzowatość czy wadę i jakie przekroje są potrzebne."},{"heading":"Praca ucznia i kryteria sprawdzenia","text":"Przygotuj trzywidokowy szkic: przód, bok i przekrój. Podpisz talerzowatość (dish), bicie boczne, bicie promieniowe, piastę i obręcz. Narysuj dwa odrębne przypadki: zaprojektowane wychylenie i deformację."}],"references":[{"label":"Źródło fachowe lub muzealne","url":"https://merl.reading.ac.uk/explore/online-exhibitions/shoulder-to-the-wheel/"}],"learning":{"intro":"Koło dawnego wozu bywa celowo ''talerzowate'' (dished): szprychy nie leżą w jednej płaskiej tarczy, lecz tworzą geometryczne wychylenie. Ma ono związek z konstrukcją, obciążeniami i stabilnością całego zestawu. To nie to samo co przypadkowe boczne bicie koła. Rysunek musi pokazywać widok z przodu i przekrój przez piastę, a także stronę montażu koła względem pojazdu.","situation":"Praktykant widzi, że piasta nie jest w tej samej płaszczyźnie co obręcz, więc chce prostować wszystkie szprychy. Ustal, czy widzi zaprojektowaną talerzowatość czy wadę i jakie przekroje są potrzebne.","task":"Przygotuj trzywidokowy szkic: przód, bok i przekrój. Podpisz talerzowatość (dish), bicie boczne, bicie promieniowe, piastę i obręcz. Narysuj dwa odrębne przypadki: zaprojektowane wychylenie i deformację.","question":"Które zdanie prawidłowo odróżnia talerzowatość koła od bicia bocznego?","options":["Talerzowatość opisuje promieniową zmianę średnicy podczas obrotu.","Oba pojęcia oznaczają tylko pochylenie osi pojazdu.","Bicie boczne jest pożądanym ukształtowaniem każdej szprychy.","Talerzowatość może być zamierzoną geometrią, a bicie boczne zmiennym odchyleniem w czasie obrotu."],"correct":3,"example":"Talerzowatość może być zamierzoną geometrią, a bicie boczne zmiennym odchyleniem w czasie obrotu.","explanation":"W historycznym kole dish mógł być planowanym ukształtowaniem, a bicie trzeba mierzyć względem referencji podczas obrotu.","feedback":["Nie. Zmienne odchylenie promienia to bicie promieniowe, nie dish.","Nie. Opis osi pojazdu nie definiuje talerzowatości koła.","Nie. Bicie boczne jest mierzoną odchyłką, a nie automatycznym celem projektu.","Tak. Poprawnie: stała geometria przekroju różni się od zmiennego przesunięcia bocznego."]}}'::jsonb),
('kolodziej',4,'5. Narzędzia kołodzieja i bezpieczne stanowisko','{"module":2,"curriculum_revision":6,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"kolodziej-przekroj","sections":[{"heading":"Fundamenty i pojęcia","text":"Warsztat kołodziejski łączy obróbkę drewna, pomiary i współpracę z kowalem. Tokarka kształtuje piastę, świder przygotowuje miejsca pod gniazda, dłuto je dopracowuje, a strug do szprych (spokeshave) wygładza jej kształt. Przyrząd typu traveler — małe koło pomiarowe — pozwala porównać drogę po obwodzie drewnianym i metalowym pasie. Trzeba rozróżniać narzędzia pomiarowe, skrawające i urządzenia do podnoszenia pojazdu."},{"heading":"Narzędzia, proces i metoda","text":"Stół powinien mieć czyste strefy: rysunek i trasowanie, drewno i cięcie, kontrola geometrii, dokumentacja. Tokarki, prasy, podnośniki i gorące obręcze wymagają właściwej procedury, przeszkolenia i osłon. Ćwiczenie online ogranicza się do rozpoznania funkcji narzędzi i zaprojektowania bezpiecznej pracy — nie jest instruktażem obsługi tokarki ani pracy z gorącym metalem."},{"heading":"Przykład z liczbami lub pomiarem","text":"Uczeń ma przygotować kształt szprychy, ale wybiera traveler, którym mierzy się obwód. Narzędzie nie wykona operacji skrawania, choć jest związane z wytwarzaniem koła. Lepszą odpowiedzią do kształtowania będzie odpowiedni strug albo narzędzie specjalistyczne dobrane przez instruktora."},{"heading":"Sytuacja zawodowa","text":"Na podłodze leżą ostrza obok podnośnika, a pracownik chce przesunąć ciężkie koło bez zabezpieczenia. Zaproponuj rozmieszczenie stanowiska i odpowiedzialności, zanim rozpocznie się praktyka."},{"heading":"Praca ucznia i kryteria sprawdzenia","text":"Narysuj 8 narzędzi i przypisz im: funkcję, podstawowy pomiar lub rezultat, zagrożenie i punkt kontroli. Zaznacz wyraźnie, które narzędzia wymagają nadzoru instruktora oraz przeglądów bezpieczeństwa."}],"references":[{"label":"Źródło fachowe lub muzealne","url":"https://metc.org/decoding-the-past-wheelwright/"}],"learning":{"intro":"Warsztat kołodziejski łączy obróbkę drewna, pomiary i współpracę z kowalem. Tokarka kształtuje piastę, świder przygotowuje miejsca pod gniazda, dłuto je dopracowuje, a strug do szprych (spokeshave) wygładza jej kształt. Przyrząd typu traveler — małe koło pomiarowe — pozwala porównać drogę po obwodzie drewnianym i metalowym pasie. Trzeba rozróżniać narzędzia pomiarowe, skrawające i urządzenia do podnoszenia pojazdu.","situation":"Na podłodze leżą ostrza obok podnośnika, a pracownik chce przesunąć ciężkie koło bez zabezpieczenia. Zaproponuj rozmieszczenie stanowiska i odpowiedzialności, zanim rozpocznie się praktyka.","task":"Narysuj 8 narzędzi i przypisz im: funkcję, podstawowy pomiar lub rezultat, zagrożenie i punkt kontroli. Zaznacz wyraźnie, które narzędzia wymagają nadzoru instruktora oraz przeglądów bezpieczeństwa.","question":"Którego narzędzia używano historycznie do porównywania obwodu drewnianego koła z długością żelaznego pasa na obręcz?","options":["Strugiem do szprych (spokeshave).","Przyrządem traveler, czyli kołem pomiarowym.","Świdrem do gniazd w piaście.","Kątomierzem do podziału szprych."],"correct":1,"example":"Przyrządem traveler, czyli kołem pomiarowym.","explanation":"Traveler to koło pomiarowe toczone wzdłuż mierzonych obwodów; nie służy do strugania szprych.","feedback":["Nie. Spokeshave kształtuje drewno, nie przenosi obwodu na pas metalowy.","Tak. Traveler przetacza się po obwodzie i pozwala odtworzyć drogę pomiaru.","Nie. Świder przygotowuje otwory w piaście.","Nie. Kątomierz pomaga przy podziale, nie mierzy pełnej drogi po obwodzie."]}}'::jsonb),
('kolodziej',5,'6. Piasta: oś, gniazda i symetria połączeń','{"module":2,"curriculum_revision":6,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"kolodziej-przekroj","sections":[{"heading":"Fundamenty i pojęcia","text":"Piasta łączy koło z osią i ma gniazda mocujące końce szprych. W dawnych konstrukcjach blok wiązu przygotowywano, formowano na tokarce, a otwory pod szprychy rozmieszczano według geometrii projektu. Gniazdo (mortise) i czop (tenon) muszą współpracować powierzchniami, a zbyt głębokie lub przypadkowo przesunięte wybranie może osłabić piastę. Nie należy kopiować rozstawu z innego koła bez sprawdzenia przeznaczenia."},{"heading":"Narzędzia, proces i metoda","text":"Ćwiczenie rysunkowe dla 12 szprych: pełen obwód 360°/12=30°. W widoku przednim zaznacz dwanaście osi, osobno pokazując kształt gniazda na przekroju. Uwaga: 30° to tylko plan podziału kątowego; wykonawcza geometria gniazda zależy także od talerzowatości i czopa. W praktyce tokarka i dłuta wymagają fachowego nadzoru."},{"heading":"Przykład z liczbami lub pomiarem","text":"Jeśli w jednej z 12 pozycji środek gniazda jest przesunięty, szprycha nie będzie pracowała w zaplanowanym kierunku. Warto sprawdzić układ szablonem przed rozpoczęciem obróbki zamiast korygować gotowe otwory."},{"heading":"Sytuacja zawodowa","text":"Zlecenie opisuje koło 14-szprychowe, ale gotowy wzór podziału na 12 pozycji. Wyjaśnij, dlaczego różnica kąta 30° i 360°/14≈25,71° uniemożliwia bezmyślne użycie szablonu."},{"heading":"Praca ucznia i kryteria sprawdzenia","text":"Narysuj przód piasty dla 12 szprych i policz odstęp kątowy. Potem dla 14 szprych policz odstęp i wyjaśnij różnicę. Zaznacz położenie otworu osiowego, grubość ścianki i obszar gniazda bez podawania wymiarów pasowania bez projektu."}],"references":[{"label":"Źródło fachowe lub muzealne","url":"https://www.hessenpark.de/en/lexikon/handwerk/vorfuehrungen/wagnerei/"}],"learning":{"intro":"Piasta łączy koło z osią i ma gniazda mocujące końce szprych. W dawnych konstrukcjach blok wiązu przygotowywano, formowano na tokarce, a otwory pod szprychy rozmieszczano według geometrii projektu. Gniazdo (mortise) i czop (tenon) muszą współpracować powierzchniami, a zbyt głębokie lub przypadkowo przesunięte wybranie może osłabić piastę. Nie należy kopiować rozstawu z innego koła bez sprawdzenia przeznaczenia.","situation":"Zlecenie opisuje koło 14-szprychowe, ale gotowy wzór podziału na 12 pozycji. Wyjaśnij, dlaczego różnica kąta 30° i 360°/14≈25,71° uniemożliwia bezmyślne użycie szablonu.","task":"Narysuj przód piasty dla 12 szprych i policz odstęp kątowy. Potem dla 14 szprych policz odstęp i wyjaśnij różnicę. Zaznacz położenie otworu osiowego, grubość ścianki i obszar gniazda bez podawania wymiarów pasowania bez projektu.","question":"W prostym modelu 12 szprych równomiernie rozmieszczonych wokół piasty odstęp kątowy wynosi...","options":["25,7°, bo 360° dzieli się przez 14.","22,5°, bo 360° dzieli się przez 16.","30°, bo 360° dzieli się przez 12.","45°, bo cztery osie dają ćwiartki koła."],"correct":2,"example":"30°, bo 360° dzieli się przez 12.","explanation":"360°/12=30°. Rzeczywisty profil gniazd wymaga niezależnej dokumentacji technicznej.","feedback":["Nie. To wynik dla 14 szprych.","Nie. To wynik dla 16 szprych.","Tak. Tak: 360/12=30°.","Nie. 45° odpowiada ośmiu równym pozycjom, nie dwunastu."]}}'::jsonb),
('kolodziej',6,'7. Szprycha: włókna, czopy i kontrola jednakowego podparcia','{"module":2,"curriculum_revision":6,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"kolodziej-drewno","sections":[{"heading":"Fundamenty i pojęcia","text":"Szprycha musi być poprawnie dopasowana do piasty i dzwona. Tradycyjnie wykorzystywano odpowiednio sezonowany dąb i formowano zgrubnie narzędziami ciesielskimi, następnie dopracowywano strugiem. Koniec piastowy ma czop odpowiadający gniazdu, a koniec zewnętrzny współpracuje z drewnianym obwodem. Kluczowe są ciągłość włókien, kontrola przekroju, kształt powierzchni oparcia oraz zgodność z projektową geometrią."},{"heading":"Narzędzia, proces i metoda","text":"Nie zaczynaj od obcięcia wszystkich szprych ''na jeden wymiar'', jeżeli projekt ma talerzowatość albo zróżnicowane miejsca podparcia. Ustal bazę pomiarową między gniazdem piasty a gniazdem w dzwonie, dodaj wymiary czopów zgodnie z rysunkiem oraz pomiaru po montażu. Model z papieru lub kartonu pozwala sprawdzić położenie końców bez pracy na maszynach."},{"heading":"Przykład z liczbami lub pomiarem","text":"Załóż dla lekcji 14 osi szprych. Równy podział to około 25,714°. Dwa sąsiednie czopy mają inny profil — sama równa odległość kątowa nie zapewnia powtarzalnego oparcia. Wady trzeba opisać i porównać ze specyfikacją."},{"heading":"Sytuacja zawodowa","text":"Jedna szprycha ma duże pęknięcie blisko czopa, ale jej widoczna długość jest idealna. Ustal, dlaczego pomiar długości nie wystarcza do jej przyjęcia jako elementu nośnego."},{"heading":"Praca ucznia i kryteria sprawdzenia","text":"Wykonaj kartę sześciu szprych z kolumnami: oś/rozstaw, gatunek i włókna, kształt czopa, widoczna wada, decyzja o przyjęciu, źródło wymiaru. Zapisz, co można pomierzyć na modelu, a co wymaga fachowej oceny obciążenia."}],"references":[{"label":"Źródło fachowe lub muzealne","url":"https://merl.reading.ac.uk/explore/online-exhibitions/shoulder-to-the-wheel/"}],"learning":{"intro":"Szprycha musi być poprawnie dopasowana do piasty i dzwona. Tradycyjnie wykorzystywano odpowiednio sezonowany dąb i formowano zgrubnie narzędziami ciesielskimi, następnie dopracowywano strugiem. Koniec piastowy ma czop odpowiadający gniazdu, a koniec zewnętrzny współpracuje z drewnianym obwodem. Kluczowe są ciągłość włókien, kontrola przekroju, kształt powierzchni oparcia oraz zgodność z projektową geometrią.","situation":"Jedna szprycha ma duże pęknięcie blisko czopa, ale jej widoczna długość jest idealna. Ustal, dlaczego pomiar długości nie wystarcza do jej przyjęcia jako elementu nośnego.","task":"Wykonaj kartę sześciu szprych z kolumnami: oś/rozstaw, gatunek i włókna, kształt czopa, widoczna wada, decyzja o przyjęciu, źródło wymiaru. Zapisz, co można pomierzyć na modelu, a co wymaga fachowej oceny obciążenia.","question":"Co jest najsilniejszym argumentem za odrzuceniem szprychy mimo prawidłowej długości?","options":["Niewielka różnica barwy między odcinkami szprychy.","Pęknięcie przechodzące przez strefę czopa przenoszącego obciążenie.","Nieco odmienny odcień drewna po olejowaniu.","Widoczne słoje bez przerwania ciągłości materiału."],"correct":1,"example":"Pęknięcie przechodzące przez strefę czopa przenoszącego obciążenie.","explanation":"Pęknięcie w strefie przenoszenia sił może osłabić połączenie, choć wymiar zewnętrzny pozostaje prawidłowy.","feedback":["Nie. Sam kolor jest słabą przesłanką do oceny wytrzymałości.","Tak. Pęknięcie w obszarze czopa może zagrozić całemu połączeniu.","Nie. Odcień po wykończeniu nie stanowi dowodu uszkodzenia strukturalnego.","Nie. Widoczne słoje są normalną cechą drewna, o ile nie towarzyszy im wada."]}}'::jsonb),
('kolodziej',7,'8. Dzwona: segmenty łuku, połączenia i geometria obręczy','{"module":2,"curriculum_revision":6,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"kolodziej-geometria","sections":[{"heading":"Fundamenty i pojęcia","text":"Dzwona to zakrzywione drewniane segmenty tworzące obwód koła. Są osadzane na końcach szprych i łączone między sobą zgodnie z historycznym rozwiązaniem. Na przykładzie muzealnego koła z 14 szprychami i 7 dzwonami widać, że liczba segmentów nie musi być równa liczbie szprych. Kształt segmentu trzeba określić na łuku, a nie wycinać proste odcinki o długości obliczonej z obwodu."},{"heading":"Narzędzia, proces i metoda","text":"Dla idealnego koła D=900 mm i 8 dzwon obwód wynosi 900π≈2827,43 mm; długość łuku przypadająca na jeden segment to ~353,43 mm. Prosta cięciwa między końcami tego samego łuku ma długość 2R sin(π/8)=900 sin(22,5°)≈344,42 mm. Różnica około 9 mm pokazuje, że łuk i prosta cięciwa nie są tym samym. Są to wartości geometrii, nie szablon z naddatkami i wymiarami połączeń."},{"heading":"Przykład z liczbami lub pomiarem","text":"Ktoś dzieli obwód przez 8 i odmierza po 353,4 mm prostej od linii do linii na desce, zakładając, że dostanie idealny ośmiobok. Zapomina o różnicy między łukiem, cięciwą i rzeczywistym profilem dzwona; po złożeniu mogą powstać niedopasowania."},{"heading":"Sytuacja zawodowa","text":"Projekt ma 8 segmentów i 16 szprych, ale materiał na dwa segmenty ma pęknięcia czołowe. Wyjaśnij, dlaczego nie należy wymuszać dopasowania obręczą ani zamieniać ich na przypadkowe proste listwy."},{"heading":"Praca ucznia i kryteria sprawdzenia","text":"Narysuj koło D=900 mm z 8 dzwonami. Porównaj teoretyczny łuk 353,43 mm z cięciwą 344,42 mm. Oznacz miejsca styku, gniazda szprych i części, których nadal brak do wykonania szablonu (szerokość, grubość, profil, czopy, naddatki)."}],"references":[{"label":"Źródło fachowe lub muzealne","url":"https://museum.wales/collections/online/object/c92c1c74-5534-34bf-91d5-b6ade7331896/Cart-wheel/"}],"learning":{"intro":"Dzwona to zakrzywione drewniane segmenty tworzące obwód koła. Są osadzane na końcach szprych i łączone między sobą zgodnie z historycznym rozwiązaniem. Na przykładzie muzealnego koła z 14 szprychami i 7 dzwonami widać, że liczba segmentów nie musi być równa liczbie szprych. Kształt segmentu trzeba określić na łuku, a nie wycinać proste odcinki o długości obliczonej z obwodu.","situation":"Projekt ma 8 segmentów i 16 szprych, ale materiał na dwa segmenty ma pęknięcia czołowe. Wyjaśnij, dlaczego nie należy wymuszać dopasowania obręczą ani zamieniać ich na przypadkowe proste listwy.","task":"Narysuj koło D=900 mm z 8 dzwonami. Porównaj teoretyczny łuk 353,43 mm z cięciwą 344,42 mm. Oznacz miejsca styku, gniazda szprych i części, których nadal brak do wykonania szablonu (szerokość, grubość, profil, czopy, naddatki).","question":"Dla idealnego koła D=900 mm i 8 równych dzwon długość łuku i prostej cięciwy na jeden segment są...","options":["Łuk około 344,4 mm; cięciwa około 353,4 mm.","Oba odcinki są równe 353,4 mm.","Łuk 112,5 mm; cięciwa 900 mm.","Łuk około 353,4 mm; cięciwa około 344,4 mm."],"correct":3,"example":"Łuk około 353,4 mm; cięciwa około 344,4 mm.","explanation":"Łuk 900π/8≈353,43 mm; cięciwa 900 sin(22,5°)≈344,42 mm. To dwa różne wymiary geometryczne.","feedback":["Nie. To odwrócenie obliczonych wielkości; łuk jest dłuższy od cięciwy.","Nie. Nie: odcinki krzywoliniowy i prosty między tymi samymi końcami nie są równe.","Nie. 112,5 pochodziłoby z błędnego podziału samej średnicy przez 8.","Tak. 900π/8≈353,4 mm; 900 sin 22,5°≈344,4 mm."]}}'::jsonb),
('kolodziej',8,'9. Obręcz żelazna: rozszerzalność i pasowanie skurczowe','{"module":3,"curriculum_revision":6,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"kolodziej-przekroj","sections":[{"heading":"Zrozum zjawisko","text":"Zewnętrzna metalowa obręcz chroni dzwona i może utrzymywać drewniane segmenty koła w docisku. Historycznie przygotowywano ciągły pierścień metalowy, a kowal nagrzewał go, aby umożliwić osadzenie na drewnianym obwodzie. Przy chłodzeniu metal kurczył się, obejmując koło. To nie jest jedynie malowana taśma ochronna ani dowolnie dobrany pierścień."},{"heading":"Przeanalizuj technologię i dane","text":"Narysuj trzy stany: zimna obręcz, rozszerzona pod wpływem ciepła, ponownie schłodzona. Sprawdź, dlaczego wynik zależy od realnego obwodu, stanu dzwon, metalu i warunków technicznych. Wartości temperatur, spoiny i interferencji nie można przenosić z przypadkowego przykładu: konieczne jest doświadczenie kowala oraz ocena konstrukcji."},{"heading":"Przykład techniczny","text":"Dla idealnego D=900 mm teoretyczne C≈2827 mm. Nie jest to długość produkcyjna metalowej obręczy, ponieważ brakuje wymiaru osadzenia, właściwości materiału i wymaganego pasowania."},{"heading":"Sytuacja zawodowa","text":"Obręcz starego koła jest luźna po latach magazynowania; ktoś proponuje ją bez badań mocno nagrzać. Rozpoznaj ryzyko pęknięcia drewna, poparzeń i niekontrolowanego docisku."},{"heading":"Zadanie z kryteriami","text":"Narysuj stan przed, w trakcie i po montażu. Podpisz zmianę wymiaru, docisk i cztery ryzyka. Wypisz, jakie dane musi posiadać fachowiec, by rozstrzygnąć sposób naprawy."}],"references":[{"label":"Źródło muzealne / techniczne","url":"https://templetonmuseum.com/portfolio-items/blacksmith-shop/"}],"learning":{"intro":"Zewnętrzna metalowa obręcz chroni dzwona i może utrzymywać drewniane segmenty koła w docisku. Historycznie przygotowywano ciągły pierścień metalowy, a kowal nagrzewał go, aby umożliwić osadzenie na drewnianym obwodzie. Przy chłodzeniu metal kurczył się, obejmując koło. To nie jest jedynie malowana taśma ochronna ani dowolnie dobrany pierścień.","situation":"Obręcz starego koła jest luźna po latach magazynowania; ktoś proponuje ją bez badań mocno nagrzać. Rozpoznaj ryzyko pęknięcia drewna, poparzeń i niekontrolowanego docisku.","task":"Narysuj stan przed, w trakcie i po montażu. Podpisz zmianę wymiaru, docisk i cztery ryzyka. Wypisz, jakie dane musi posiadać fachowiec, by rozstrzygnąć sposób naprawy.","question":"Dlaczego gorącą obręcz można było nałożyć, a po ostygnięciu uzyskać docisk?","options":["Wstępne ogrzanie usuwa potrzebę pomiaru obwodu.","Metal ma taki sam wymiar przy każdej temperaturze.","Obręcz rozszerza się podczas nagrzania, a po chłodzeniu może docisnąć drewniany obwód.","Drewno podczas chłodzenia metalu musi skurczyć się dokładnie o tyle samo."],"correct":2,"example":"Obręcz rozszerza się podczas nagrzania, a po chłodzeniu może docisnąć drewniany obwód.","explanation":"To zasada rozszerzalności cieplnej metalu i skurczu po ochłodzeniu. Wymiary muszą dobrać specjaliści.","feedback":["Nie. Pasowanie i wymiar obręczy nadal wymagają kontroli.","Nie. Wymiary metalu zmieniają się z temperaturą.","Tak. Tak: to podstawowy mechanizm pasowania skurczowego.","Nie. Różne materiały pracują inaczej; nie ma takiej konieczności."]}}'::jsonb),
('kolodziej',9,'10. Traveler — przyrząd do pomiaru i porównania obwodu','{"module":3,"curriculum_revision":6,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"kolodziej-geometria","sections":[{"heading":"Zrozum zjawisko","text":"Traveler, zwany też kołem pomiarowym kołodzieja, był toczony wzdłuż drewnianego obwodu, a następnie po pasie żelaza. Znacznik punktu startowego i liczba pełnych oraz niepełnych obrotów pozwalały przenosić pomiar. Rzeczywiste koło bywa mniej idealne niż model C=πD; oba sposoby dostarczają informacji do porównania."},{"heading":"Przeanalizuj technologię i dane","text":"W dydaktycznym modelu przyrząd o średnicy 100 mm przebywa w jednym obrocie π×100≈314,16 mm. Pięć obrotów bez poślizgu to około 1571 mm. Podczas praktycznego pomiaru zapisuje się początek, kierunek toczenia, poślizg i błędy odczytu; realnej obręczy nie wymiaruje się jedynie na podstawie szkolnego równania."},{"heading":"Przykład techniczny","text":"Dla D=900 mm teoretyczne C≈2827,4 mm, lecz przyrząd na nierównym kole pokazuje 2818 mm. Różnica około 9,4 mm jest sygnałem do ponownego pomiaru, a nie gotowym parametrem docisku."},{"heading":"Sytuacja zawodowa","text":"Praktykant pomylił liczbę pełnych obrotów travelera z liczbą obrotów koła wozu. Zaprojektuj zapis pomiarowy, który rozdziela oba pojęcia."},{"heading":"Zadanie z kryteriami","text":"Narysuj traveler i jego znacznik. Policz dystans 5 obrotów dla d=100 mm oraz porównaj obwód teoretyczny i zmierzony. Podaj trzy źródła możliwego błędu."}],"references":[{"label":"Źródło muzealne / techniczne","url":"https://dominycollections.winterthur.org/tools-of-the-trade/woodworking/traveler/"}],"learning":{"intro":"Traveler, zwany też kołem pomiarowym kołodzieja, był toczony wzdłuż drewnianego obwodu, a następnie po pasie żelaza. Znacznik punktu startowego i liczba pełnych oraz niepełnych obrotów pozwalały przenosić pomiar. Rzeczywiste koło bywa mniej idealne niż model C=πD; oba sposoby dostarczają informacji do porównania.","situation":"Praktykant pomylił liczbę pełnych obrotów travelera z liczbą obrotów koła wozu. Zaprojektuj zapis pomiarowy, który rozdziela oba pojęcia.","task":"Narysuj traveler i jego znacznik. Policz dystans 5 obrotów dla d=100 mm oraz porównaj obwód teoretyczny i zmierzony. Podaj trzy źródła możliwego błędu.","question":"Traveler o średnicy 100 mm przetoczył się bez poślizgu przez pięć pełnych obrotów. Jaka jest droga?","options":["500 mm — pięć obrotów oznacza pięć średnic.","Około 1571 mm — pięć razy π×100 mm.","Około 314 mm — tyle samo niezależnie od liczby obrotów.","Około 2827 mm — odpowiada kołu o średnicy 900 mm."],"correct":1,"example":"Około 1571 mm — pięć razy π×100 mm.","explanation":"5×π×100≈1571 mm.","feedback":["Nie. Na jeden obrót przypada obwód koła pomiarowego, nie jego średnica.","Tak. Pięć razy około 314,16 mm daje około 1571 mm.","Nie. 314 mm dotyczy jednego, nie pięciu obrotów.","Nie. 2827 mm to obwód innego koła, podanego dla porównania."]}}'::jsonb),
('kolodziej',10,'11. Piasta, oś i statyczna droga obciążeń','{"module":3,"curriculum_revision":6,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"kolodziej-przekroj","sections":[{"heading":"Zrozum zjawisko","text":"Piasta współpracuje z osią i tworzy centralną strefę przenoszenia sił. Dawne rozwiązania miały różne tuleje, czopy i zabezpieczenia. Nie zakładaj, że każde historyczne koło ma identyczne smarowanie, łożyskowanie i luz. Obciążenie przechodzi przez konstrukcję do podłoża, a nierówna droga i zakręty dodatkowo obciążają połączenia."},{"heading":"Przeanalizuj technologię i dane","text":"Na schemacie zaznacz oś, piastę, otwór, szprychy i reakcję podłoża. W uproszczonym modelu masy 600 kg równomiernie rozłożonej na 4 koła przypada 150 kg na koło. Przy g=9,81 m/s² jest to około 1472 N statycznej siły ciężaru. Prawdziwy nacisk może być wyższy podczas jazdy lub nierównego rozłożenia ładunku."},{"heading":"Przykład techniczny","text":"Model 600/4=150 kg nie wyznacza dopuszczalnej nośności piasty. Wartość 1472 N jest tylko wycinkiem obliczeń, bez dynamicznego obciążenia i kontroli zużycia osi."},{"heading":"Sytuacja zawodowa","text":"W piaście istnieje pęknięcie przy otworze i widoczny luz. Sama wymiana metalowej obręczy nie rozwiązuje problemu łożyskowania ani oceny bezpieczeństwa pojazdu."},{"heading":"Zadanie z kryteriami","text":"Zapisz pięć punktów kontroli osi i piasty: luz osiowy, promieniowy, ślady zużycia, pęknięcia i zabezpieczenie. Oblicz statyczny model 1472 N i wyjaśnij jego ograniczenia."}],"references":[{"label":"Źródło muzealne / techniczne","url":"https://museum.wales/collections/online/object/c92c1c74-5534-34bf-91d5-b6ade7331896/Cart-wheel/"}],"learning":{"intro":"Piasta współpracuje z osią i tworzy centralną strefę przenoszenia sił. Dawne rozwiązania miały różne tuleje, czopy i zabezpieczenia. Nie zakładaj, że każde historyczne koło ma identyczne smarowanie, łożyskowanie i luz. Obciążenie przechodzi przez konstrukcję do podłoża, a nierówna droga i zakręty dodatkowo obciążają połączenia.","situation":"W piaście istnieje pęknięcie przy otworze i widoczny luz. Sama wymiana metalowej obręczy nie rozwiązuje problemu łożyskowania ani oceny bezpieczeństwa pojazdu.","task":"Zapisz pięć punktów kontroli osi i piasty: luz osiowy, promieniowy, ślady zużycia, pęknięcia i zabezpieczenie. Oblicz statyczny model 1472 N i wyjaśnij jego ograniczenia.","question":"Masa 600 kg równomiernie podzielona na 4 koła oznacza modelową statyczną siłę na koło równą...","options":["Około 1472 N na koło przy rozłożeniu masy 600 kg na cztery.","Około 5886 N na każde koło, bo 600×9,81.","Około 600 N na koło, bo masa ma 600 kg.","Około 150 N na koło, bo na koło przypada 150 kg."],"correct":0,"example":"Około 1472 N na koło przy rozłożeniu masy 600 kg na cztery.","explanation":"600/4×9,81≈1471,5 N.","feedback":["Tak. 150 kg×9,81≈1472 N, przy idealnym równym podziale obciążenia.","Nie. 5886 N to suma ciężaru dla 600 kg, a nie jedna czwarta.","Nie. Masa w kg nie jest wartością siły w niutonach.","Nie. 150 kg to masa przypadająca na koło, a siła to około 1472 N."]}}'::jsonb),
('kolodziej',11,'12. Bicie boczne i promieniowe — pomiar odchyłek','{"module":3,"curriculum_revision":6,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"kolodziej-bicie","sections":[{"heading":"Zrozum zjawisko","text":"Bicie promieniowe opisuje różnice promienia przy obrocie względem osi, bicie boczne — zmienne przesuwanie obręczy w bok. Nie myl ich z zaprojektowaną talerzowatością, która jest stałą cechą geometrii koła. Każdy pomiar wymaga stabilnego punktu odniesienia, identyfikacji miejsca i zapisu wartości maksymalnej oraz minimalnej."},{"heading":"Przeanalizuj technologię i dane","text":"W ćwiczeniu promień maksymalny wynosi 451 mm, minimalny 446 mm; rozrzut to 5 mm. Pomiar boczny od -2 do +3 mm także daje całkowity rozrzut 5 mm. To odczyty opisujące geometrię; bez dokumentacji producenta lub historycznych kryteriów nie można twierdzić, że 5 mm jest dopuszczalne lub niedopuszczalne."},{"heading":"Przykład techniczny","text":"Koło ma założony dish 20 mm i jednocześnie zmienne bicie boczne 5 mm. Nie prostuj zaprojektowanej talerzowatości w ramach eliminowania zmiennego bicia."},{"heading":"Sytuacja zawodowa","text":"Operator obserwuje zmianę odległości od wskaźnika promieniowego, ale chce regulować boczne ustawienie piasty. Oceń, czy jego działanie odpowiada rodzajowi wady."},{"heading":"Zadanie z kryteriami","text":"Na rysunku koła oznacz kierunek radialny i boczny. Oblicz dwie różnice 451−446 i 3−(-2). Zapisz, jak odróżnia się stały offset od zmiennego bicia."}],"references":[{"label":"Źródło muzealne / techniczne","url":"https://merl.reading.ac.uk/explore/online-exhibitions/shoulder-to-the-wheel/"}],"learning":{"intro":"Bicie promieniowe opisuje różnice promienia przy obrocie względem osi, bicie boczne — zmienne przesuwanie obręczy w bok. Nie myl ich z zaprojektowaną talerzowatością, która jest stałą cechą geometrii koła. Każdy pomiar wymaga stabilnego punktu odniesienia, identyfikacji miejsca i zapisu wartości maksymalnej oraz minimalnej.","situation":"Operator obserwuje zmianę odległości od wskaźnika promieniowego, ale chce regulować boczne ustawienie piasty. Oceń, czy jego działanie odpowiada rodzajowi wady.","task":"Na rysunku koła oznacz kierunek radialny i boczny. Oblicz dwie różnice 451−446 i 3−(-2). Zapisz, jak odróżnia się stały offset od zmiennego bicia.","question":"Odchyłki boczne wynoszą od -2 mm do +3 mm. Ile wynosi cały rozrzut?","options":["1 mm — dodajemy wartości z przeciwnymi znakami bez ich uwzględniania.","2 mm — tylko wartość minimalnego odchylenia.","3 mm — tylko wartość maksymalnego odchylenia.","5 mm — różnica między +3 a -2."],"correct":3,"example":"5 mm — różnica między +3 a -2.","explanation":"3−(-2)=5 mm.","feedback":["Nie. Rozrzut obejmuje pełny zakres między przeciwległymi znakami.","Nie. 2 mm to tylko odległość min od zera.","Nie. 3 mm to tylko odległość max od zera.","Tak. Różnica 3-(-2)=5 mm."]}}'::jsonb),
('kolodziej',12,'13. Wilgotność, luźna obręcz i konserwacja koła','{"module":4,"curriculum_revision":6,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"kolodziej-drewno","sections":[{"heading":"Zrozum zjawisko","text":"Drewno pracuje pod wpływem zmian wilgotności, co może wpływać na napięcie połączeń. Wysuszenie drewnianego obwodu bywa historycznie wskazywaną przyczyną poluzowania metalowej obręczy. Woda i zmiany otoczenia mogą także przyspieszać korozję, odkształcenia i degradację drewna. Ocena wymaga obserwacji całego układu, a nie tylko samej powierzchni."},{"heading":"Przeanalizuj technologię i dane","text":"Karta przeglądu uwzględnia stan dzwon, szprych i czopów, miejscowe pęknięcia, luz obręczy, ślady korozji, stan powierzchni łożyskowania oraz warunki składowania. Prace przy stalowej obręczy i czynnej bryczce pozostaw fachowcom. Zmoczenie drewna bez planu może spowodować nowe problemy."},{"heading":"Przykład techniczny","text":"Pemberton Museum opisuje narzędzie do skracania luźnej obręczy (tire upsetter), używane np. po wysychaniu koła. To świadectwo historii techniki, nie instrukcja współczesnej naprawy dla początkującego."},{"heading":"Sytuacja zawodowa","text":"Po suchym lecie obręcz obraca się lekko względem drewnianego obwodu. Właściciel chce tylko nasmarować piastę. Wyjaśnij, dlaczego to inny problem i dlaczego koła nie należy używać przed kontrolą."},{"heading":"Zadanie z kryteriami","text":"Opracuj checklistę dwunastu punktów: część, objaw, podejrzenie, pomiar, zdjęcie, decyzja. Odróżnij luźną obręcz od luzu piasty i pęknięcia szprychy."}],"references":[{"label":"Źródło muzealne / techniczne","url":"https://www.pembertonmuseum.org/objects/tire-upsetter/"}],"learning":{"intro":"Drewno pracuje pod wpływem zmian wilgotności, co może wpływać na napięcie połączeń. Wysuszenie drewnianego obwodu bywa historycznie wskazywaną przyczyną poluzowania metalowej obręczy. Woda i zmiany otoczenia mogą także przyspieszać korozję, odkształcenia i degradację drewna. Ocena wymaga obserwacji całego układu, a nie tylko samej powierzchni.","situation":"Po suchym lecie obręcz obraca się lekko względem drewnianego obwodu. Właściciel chce tylko nasmarować piastę. Wyjaśnij, dlaczego to inny problem i dlaczego koła nie należy używać przed kontrolą.","task":"Opracuj checklistę dwunastu punktów: część, objaw, podejrzenie, pomiar, zdjęcie, decyzja. Odróżnij luźną obręcz od luzu piasty i pęknięcia szprychy.","question":"Jaka hipoteza jest sensowna przy poluzowanej obręczy po długim okresie wysychania?","options":["Drewno mogło wyschnąć i zmniejszyć wymiary poprzeczne, osłabiając docisk obręczy.","Metalowa obręcz musi wtedy zwiększyć średnicę dokładnie o 10%.","Obręcz nie ma wpływu na połączenia dzwon.","Luz zawsze dowodzi pęknięcia osi pojazdu."],"correct":0,"example":"Drewno mogło wyschnąć i zmniejszyć wymiary poprzeczne, osłabiając docisk obręczy.","explanation":"Zmiany wilgotności drewna mogą wpłynąć na pasowanie i docisk obręczy.","feedback":["Tak. To prawdopodobny mechanizm wymagający pomiaru i oceny.","Nie. Nie ma podstaw do założenia konkretnego 10-procentowego przyrostu obręczy.","Nie. Obręcz może stabilizować i dociskać drewniany obwód.","Nie. Luz obręczy i pęknięcie osi to odrębne zjawiska."]}}'::jsonb),
('kolodziej',13,'14. Konserwacja eksponatu a bezpieczny pojazd użytkowy','{"module":4,"curriculum_revision":6,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"kolodziej-przekroj","sections":[{"heading":"Zrozum zjawisko","text":"Restauracja historycznego obiektu nie oznacza automatycznego przywrócenia sprawności do przewozu osób. Zabytkowe koło ma cechy dokumentujące dawną technikę: ślady narzędzi, sygnatury, oryginalne powłoki i naprawy. Nierozważna wymiana wszystkich szprych lub intensywne szlifowanie może usunąć te informacje. Koło przeznaczone do ruchu wymaga osobnej oceny konstrukcji, osi, obciążeń i przepisów."},{"heading":"Przeanalizuj technologię i dane","text":"W protokole konserwacji zapisz numer obiektu, stan przed pracą, zdjęcia, wymiary, materiały, ślady napraw, cel właściciela i niepewności. Odróżnij stabilizację eksponatu od naprawy funkcjonalnej. Dla przewozu ludzi niezbędna jest fachowa ocena całego pojazdu — rysunek edukacyjny nie nadaje dopuszczenia do jazdy."},{"heading":"Przykład techniczny","text":"Dwa koła wyglądają podobnie; pierwsze ma wisieć w muzeum, drugie ma pracować w zaprzęgu. W pierwszym ważne jest zachowanie autentyczności, w drugim dodatkowo potwierdzenie bezpieczeństwa ruchu i nośności."},{"heading":"Sytuacja zawodowa","text":"Na starym kole znaleziono pęknięty czop, korozję i ślad wcześniejszego spawu. Klient chce po odbiorze zabrać pasażerów. Należy odmówić potwierdzenia sprawności do czasu kompetentnej oceny."},{"heading":"Zadanie z kryteriami","text":"Przygotuj dwie karty zlecenia: ekspozycja i jazda. Wypisz cel, dokument, kryteria odbioru, wymagany specjalista i zakres odpowiedzialności."}],"references":[{"label":"Źródło muzealne / techniczne","url":"https://research.colonialwilliamsburg.org/Foundation/journal/Winter04-05/wheel.cfm"}],"learning":{"intro":"Restauracja historycznego obiektu nie oznacza automatycznego przywrócenia sprawności do przewozu osób. Zabytkowe koło ma cechy dokumentujące dawną technikę: ślady narzędzi, sygnatury, oryginalne powłoki i naprawy. Nierozważna wymiana wszystkich szprych lub intensywne szlifowanie może usunąć te informacje. Koło przeznaczone do ruchu wymaga osobnej oceny konstrukcji, osi, obciążeń i przepisów.","situation":"Na starym kole znaleziono pęknięty czop, korozję i ślad wcześniejszego spawu. Klient chce po odbiorze zabrać pasażerów. Należy odmówić potwierdzenia sprawności do czasu kompetentnej oceny.","task":"Przygotuj dwie karty zlecenia: ekspozycja i jazda. Wypisz cel, dokument, kryteria odbioru, wymagany specjalista i zakres odpowiedzialności.","question":"Dlaczego estetycznie odnowione koło nie musi być bezpieczne do jazdy?","options":["Przewóz ludzi wymaga jedynie odmalowania zewnętrznej powierzchni.","Ocena estetyczna nie potwierdza nośności osi, piasty, czopów i obręczy.","Po odnowieniu koło jest zawsze konstrukcyjnie identyczne z nowym.","Badanie geometrii jest wystarczające bez analizy drewna."],"correct":1,"example":"Ocena estetyczna nie potwierdza nośności osi, piasty, czopów i obręczy.","explanation":"Ocena wizualna i konstrukcyjna to odrębne kryteria, szczególnie przy przewozie ludzi.","feedback":["Nie. Wygląd nie potwierdza bezpieczeństwa konstrukcji.","Tak. Właśnie dlatego potrzebna jest fachowa ocena całego pojazdu.","Nie. Naprawa może zmienić materiały, geometrię i stan połączeń.","Nie. Prawidłowa geometria nie dowodzi braku pęknięć albo zużycia."]}}'::jsonb),
('kolodziej',14,'15. Kosztorys: materiał, uzysk i robocizna kołodzieja','{"module":4,"curriculum_revision":6,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"kolodziej-geometria","sections":[{"heading":"Zrozum zjawisko","text":"Kołodziej powinien umieć przygotować listę materiałów (BOM) oraz harmonogram. W przykładowym kole potrzeba jednej piasty, 16 szprych, 8 dzwon oraz metalowej obręczy. Wycena obejmuje nie tylko drewno i metal, ale również selekcję z wad, formowanie, obróbkę gniazd i czopów, pracę kowala, transport, odbiór i rezerwę na poprawki. Koszt bezpośredni to nie zawsze koszt całkowity."},{"heading":"Przeanalizuj technologię i dane","text":"Przyjmij wyłącznie dla szkolnego przykładu: piasta 250 zł, szprychy 16×35=560 zł, dzwona 8×55=440 zł, obręcz 650 zł, materiały dodatkowe 100 zł i 16 h pracy×80=1280 zł. Suma wynosi 3280 zł. Gdy z 20 kandydatów na szprychy 4 odrzucono, uzysk wynosi 16/20=80%; przy wymaganych 16 dobrych sztukach modelowe zamówienie to 16/0,8=20 kandydatów."},{"heading":"Przykład techniczny","text":"Przy sprzedaży za 3500 zł i kosztach 3280 zł zostaje 220 zł na dalsze koszty, podatki, zysk lub ryzyko reklamacji. To nie jest zysk netto potwierdzony raportem."},{"heading":"Sytuacja zawodowa","text":"Osoba planująca remont podała cenę 3500 zł jako swój zysk, bo nie rozdzieliła przychodu od kosztów. Zweryfikuj jej rachunek, dodając nieujęte koszty i status niepotwierdzonych cen."},{"heading":"Zadanie z kryteriami","text":"Utwórz tabelę BOM: pozycja, ilość, koszt jednostkowy, koszt, odrzut, termin, właściciel zadania. Porównaj wariant z 12 i 16 szprychami i zaznacz, że ceny są hipotetyczne."}],"references":[{"label":"Źródło muzealne / techniczne","url":"https://www.hessenpark.de/en/lexikon/handwerk/vorfuehrungen/wagnerei/"}],"learning":{"intro":"Kołodziej powinien umieć przygotować listę materiałów (BOM) oraz harmonogram. W przykładowym kole potrzeba jednej piasty, 16 szprych, 8 dzwon oraz metalowej obręczy. Wycena obejmuje nie tylko drewno i metal, ale również selekcję z wad, formowanie, obróbkę gniazd i czopów, pracę kowala, transport, odbiór i rezerwę na poprawki. Koszt bezpośredni to nie zawsze koszt całkowity.","situation":"Osoba planująca remont podała cenę 3500 zł jako swój zysk, bo nie rozdzieliła przychodu od kosztów. Zweryfikuj jej rachunek, dodając nieujęte koszty i status niepotwierdzonych cen.","task":"Utwórz tabelę BOM: pozycja, ilość, koszt jednostkowy, koszt, odrzut, termin, właściciel zadania. Porównaj wariant z 12 i 16 szprychami i zaznacz, że ceny są hipotetyczne.","question":"Cena sprzedaży 3500 zł, przykładowe koszty 3280 zł. Jaka pozostaje kwota przed pozostałymi kosztami i podatkami?","options":["3280 zł — to suma kosztów, nie pozostała kwota.","3500 zł — to przychód przed kosztami.","220 zł — różnica ceny i wskazanych kosztów.","780 zł — nie wynika z danych zadania."],"correct":2,"example":"220 zł — różnica ceny i wskazanych kosztów.","explanation":"3500−3280=220 zł, ale to niekoniecznie zysk netto.","feedback":["Nie. To wartość kosztów w modelu.","Nie. To przychód, nie pozostała kwota.","Tak. 3500−3280=220 zł przed innymi kosztami i podatkami.","Nie. Nie ma takiej różnicy między podanymi wartościami."]}}'::jsonb),
('kolodziej',15,'16. Egzamin projektowy: koło do ekspozycji z kartą odbioru','{"module":4,"curriculum_revision":6,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"kolodziej-geometria","sections":[{"heading":"Zrozum zjawisko","text":"Zadanie końcowe integruje budowę, materiałoznawstwo, geometrię i kontrolę jakości. Projektuj wyłącznie model edukacyjny lub ekspozycyjny: D=900 mm, 16 szprych, 8 dzwon i jedna zewnętrzna obręcz. Uczeń przygotowuje widoki z przodu, z boku i przekrój przez piastę, listę części, tabelę ryzyk i projekt przeglądu. Brak danych o pasowaniu, tolerancjach i nośności trzeba jawnie wskazać zamiast wymyślać."},{"heading":"Przeanalizuj technologię i dane","text":"Oblicz obwód C=900π≈2827,43 mm, rozstaw osi szprych 360/16=22,5°, łuk jednego dzwona C/8≈353,43 mm i odpowiadającą cięciwę 900 sin 22,5°≈344,42 mm. Wyjaśnij, dlaczego te liczby nie tworzą kompletnego rysunku wykonawczego ani instrukcji instalacji gorącej obręczy."},{"heading":"Przykład techniczny","text":"Przy odbiorze widać pęknięcie czopa szprychy nr 4 i odczyt rozrzutu bicia bocznego 5 mm. Pierwszy objaw wymaga oceny materiału i przenoszenia sił; drugi odniesienia do przyjętych tolerancji. Nie można sumować ich w jedną kategorię wad."},{"heading":"Sytuacja zawodowa","text":"Muzealny model ma zostać następnego dnia wykorzystany w czynnej bryczce. Uczeń ma wyraźnie wycofać zgodę na taki zamiar i wskazać, że konieczna jest profesjonalna ocena całego pojazdu."},{"heading":"Zadanie z kryteriami","text":"Oddaj trzy widoki, cztery obliczenia, BOM, mapę co najmniej czterech usterek, 12-punktowy protokół odbioru oraz obronę decyzji o przeznaczeniu eksponatu."}],"references":[{"label":"Źródło muzealne / techniczne","url":"https://museum.wales/collections/online/object/c92c1c74-5534-34bf-91d5-b6ade7331896/Cart-wheel/"}],"learning":{"intro":"Zadanie końcowe integruje budowę, materiałoznawstwo, geometrię i kontrolę jakości. Projektuj wyłącznie model edukacyjny lub ekspozycyjny: D=900 mm, 16 szprych, 8 dzwon i jedna zewnętrzna obręcz. Uczeń przygotowuje widoki z przodu, z boku i przekrój przez piastę, listę części, tabelę ryzyk i projekt przeglądu. Brak danych o pasowaniu, tolerancjach i nośności trzeba jawnie wskazać zamiast wymyślać.","situation":"Muzealny model ma zostać następnego dnia wykorzystany w czynnej bryczce. Uczeń ma wyraźnie wycofać zgodę na taki zamiar i wskazać, że konieczna jest profesjonalna ocena całego pojazdu.","task":"Oddaj trzy widoki, cztery obliczenia, BOM, mapę co najmniej czterech usterek, 12-punktowy protokół odbioru oraz obronę decyzji o przeznaczeniu eksponatu.","question":"Który komplet wyników odpowiada modelowi D=900 mm, 16 szprych i 8 dzwon?","options":["Obwód około 900 mm i podział 45°. ","Obwód około 1800 mm i podział 16°. ","Obwód około 2827 mm i podział 30°. ","Obwód około 2827 mm i podział 22,5°."],"correct":3,"example":"Obwód około 2827 mm i podział 22,5°.","explanation":"π×900≈2827 mm, 360/16=22,5°. Dalsze wymiary muszą pochodzić z projektu.","feedback":["Nie. 900 mm jest średnicą; 45° dotyczy 8 pozycji.","Nie. Obwód 900π nie wynosi 1800, a 16° nie jest 360/16.","Nie. Obwód jest poprawny, ale 30° dotyczyłoby 12 szprych.","Tak. C=π×900≈2827 mm i 360/16=22,5°."]}}'::jsonb)
on conflict(course_slug,lesson_no) do update set title_pl=excluded.title_pl,material=public.ta_lessons.material || excluded.material,updated_at=now();
update public.ta_courses set description_pl='16 pogłębionych lekcji o rzemiośle kołodziejskim: budowa i elementy koła, dobór gatunków drewna, obliczenia geometrii, talerzowatość, tradycyjne narzędzia, piasta i czopy, szprychy i dzwona, obręcz metalowa, traveler, oś i obciążenia, bicie boczne i promieniowe, konserwacja, renowacja, kosztorys i końcowy projekt pokazowego koła. Kurs teoretyczno-projektowy, nie nadaje uprawnień do wykonania kół do pojazdów użytkowych ani do prac kowalskich.' where slug='kolodziej';
update public.ta_course_previews set
curiosity='Dlaczego piasta dawniej powstawała z wiązu, szprychy z dębu, a dzwona z jesionu — i po co kołodziejowi było koło pomiarowe traveler?',
scenario='Projektujesz pokazowe koło o średnicy 900 mm, z 16 szprychami i 8 dzwonami. Obliczasz obwód, podział kątowy i łuki, diagnozujesz bicie oraz odróżniasz eksponat od elementu bezpiecznego do jazdy.',
outcome_1='Rozpoznasz części koła, dobór drewna, budowę piasty, szprych i dzwon oraz funkcje podstawowych narzędzi.',
outcome_2='Policzysz obwód i rozstaw szprych, porównasz łuk z cięciwą, zidentyfikujesz bicie oraz rozpoznasz zasady współpracy metalu i drewna.',
outcome_3='Sporządzisz rysunek i listę materiałów, kosztorys, kartę diagnostyczną, ocenę ryzyka i projekt koła ekspozycyjnego.',
source_url='https://www.hessenpark.de/en/lexikon/handwerk/vorfuehrungen/wagnerei/',
module_titles='["I. Budowa koła i materiałoznawstwo (lekcje 1–4)","II. Warsztat, połączenia i dzwona (lekcje 5–8)","III. Obręcz, pomiary i obciążenia (lekcje 9–12)","IV. Konserwacja, projekt i kontrola (lekcje 13–16)"]'::jsonb,
review_status='review_needed',
editorial_note='Program indywidualnie opracowany, źródła muzealne i techniczne, 16 lekcji po pięć sekcji. Wymaga recenzji kołodzieja lub konserwatora, kontroli rysunków, testu zalogowanego ucznia do egzaminu końcowego i potwierdzenia publikacji ilustracji SVG w Expo. Przykładowe obliczenia nie stanowią projektu wykonawczego lub dopuszczenia pojazdu do jazdy.',
updated_at=now() where course_slug='kolodziej';
COMMIT;
